import {stages,shapes,checkGrouping,supplies,evaluatePlan} from './logic.mjs';
const stageButtons=document.querySelector('#stage-buttons');
const panel=document.querySelector('#stage-panel');
let stage='3y';let rule='color';let shapeSelection=new Set();let planSelection=new Set();let budget=8;let challenge=false;
const on=(id,event,fn)=>document.getElementById(id)?.addEventListener(event,fn);
function feedback(text){const el=document.querySelector('#feedback');el.textContent=text;}
function renderStages(){stageButtons.innerHTML=stages.map(s=>`<button type="button" class="stage-button" data-stage="${s.id}" aria-pressed="${s.id===stage}" aria-controls="stage-panel"><strong>${s.label}</strong><span>${s.mode}</span></button>`).join('');stageButtons.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{stage=b.dataset.stage;renderStages();renderPanel();stageButtons.querySelector(`[data-stage="${stage}"]`).focus();}));}
function renderPanel(){const s=stages.find(s=>s.id===stage);panel.innerHTML=`<div class="panel-head"><div><span class="pill">${s.label} · ${s.mode}</span><h3 id="stage-title">${s.title}</h3><p class="panel-copy">${s.copy}</p></div><span class="pill">Sin guardar datos</span></div><div id="activity" class="activity"></div>`;if(stage==='3y')renderShapes();else if(stage==='7y')renderPlan();else if(stage==='18m'||stage==='2y')renderCaregiver();else renderRoadmap();}
function renderShapes(){document.querySelector('#activity').innerHTML=`<p class="eyebrow">LABORATORIO DE FORMAS · CON UN ADULTO</p><fieldset><legend id="shape-rule">${rule==='color'?'Elige todas las piezas azules.':'Ahora cambia la regla: elige todos los círculos.'}</legend><p>No importa ${rule==='color'?'su forma':'su color'}. Toca una pieza para elegirla; vuelve a tocarla para quitarla.</p><div class="shape-grid">${shapes.map(s=>`<button type="button" class="choice" data-shape="${s.id}" aria-pressed="${shapeSelection.has(s.id)}"><span class="shape ${s.shape} ${s.color}" aria-hidden="true"></span><span class="choice-text">${s.name}</span></button>`).join('')}</div></fieldset><div class="controls"><button type="button" class="action primary" id="check-shapes">Comprobar mi idea</button><button type="button" class="action secondary" id="hint">Quiero una pista</button><button type="button" class="action secondary" id="reset-shapes">Empezar de nuevo</button></div><div id="feedback" class="feedback" role="status" aria-live="polite" aria-atomic="true"></div><div class="controls"><button type="button" class="action primary" id="change-rule" hidden>Probar otra regla →</button></div><div id="shape-reflection" class="reflection" hidden><h4>Ahora cuéntalo a tu manera</h4><p>¿Por qué esta pieza entra en el grupo? Puedes señalar, hablar o usar un objeto real.</p><p id="reflection-extra"></p></div><div class="transfer"><h4>De la pantalla al mundo</h4><p>Busquen dos objetos grandes de la misma forma y distinto color. ¿Qué cambia si los agrupamos de otra manera? La explicación se conversa, no se registra.</p></div>`;
 document.querySelectorAll('[data-shape]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.shape;shapeSelection.has(id)?shapeSelection.delete(id):shapeSelection.add(id);b.setAttribute('aria-pressed',String(shapeSelection.has(id)));document.querySelector('#change-rule').hidden=true;document.querySelector('#shape-reflection').hidden=true;feedback('');}));
 on('check-shapes','click',()=>{const result=checkGrouping([...shapeSelection],rule);if(result.correct){feedback(rule==='color'?'Encontraste las dos piezas azules. Tienen formas diferentes y comparten el color.':'Encontraste los dos círculos. Cambiaste la regla: ahora importa la forma.');document.querySelector('#shape-reflection').hidden=false;document.querySelector('#reflection-extra').textContent=rule==='shape'?'¿Se te ocurre otra forma de agruparlas? No hace falta seguir en pantalla.':'';document.querySelector('#change-rule').hidden=rule!=='color';}else{feedback(shapeSelection.size===0?'Todavía no hay piezas elegidas. Observa la regla y prueba con una.':result.extra.length?`Hay una pieza elegida que no sigue la regla. Busca ${rule==='color'?'el color azul, aunque cambie la forma':'los círculos, aunque cambie el color'}. Puedes cambiar tu selección.`:'Las piezas elegidas siguen la regla. ¿Falta alguna que también encaje?');}});
 on('hint','click',()=>feedback(rule==='color'?'Mira el círculo azul. ¿Qué otra pieza tiene ese mismo color? Las etiquetas también te ayudan.':'Un círculo tiene un borde redondo, sin esquinas. Hay uno de cada color.'));
 on('change-rule','click',()=>{rule='shape';shapeSelection.clear();renderShapes();document.querySelector('[data-shape]').focus();feedback('Nueva regla: elige todos los círculos.');});
 on('reset-shapes','click',()=>{rule='color';shapeSelection.clear();renderShapes();document.querySelector('[data-shape]').focus();feedback('Actividad reiniciada. Elige todas las piezas azules.');});
}
function renderPlan(){document.querySelector('#activity').innerHTML=`<p class="eyebrow">MISIÓN COTIDIANA · SITUACIÓN FICTICIA</p><h4>Prepara una salida al parque</h4><p>En esta historia, saldrás con un adulto. Necesitas agua, una merienda y revisar la ruta. Lo demás es opcional. Hay muchas soluciones posibles.</p><div class="budget" id="budget-summary" role="status" aria-live="polite" aria-atomic="true"></div><fieldset><legend>¿Qué incluirías en tu plan?</legend><div class="supply-grid">${supplies.map(s=>`<label class="supply"><input type="checkbox" value="${s.id}" ${planSelection.has(s.id)?'checked':''}><span><strong><span aria-hidden="true">${s.icon}</span> ${s.name} · ${s.cost} fichas</strong><small>${s.description}</small></span></label>`).join('')}</div></fieldset><div class="controls"><button type="button" class="action primary" id="check-plan">Revisar mi plan</button><button type="button" class="action secondary" id="plan-hint">Una pista</button><button type="button" class="action secondary" id="reset-plan">Empezar de nuevo</button></div><div id="feedback" class="feedback" role="status" aria-live="polite" aria-atomic="true"></div><div class="controls"><button type="button" class="action primary" id="challenge" hidden>¿Y si cambia el presupuesto? →</button></div><div class="reflection" id="plan-reflection" hidden><h4>Tu decisión tiene una razón</h4><p>¿Qué priorizaste? ¿Hay otra combinación posible? Explícalo en voz alta o en papel.</p></div><div class="transfer"><h4>Un paso fuera de pantalla</h4><p>Con un adulto, piensa qué llevarías a una salida real y qué ya tienes en casa. Los precios y las condiciones de esta historia son inventados; no son una lista de seguridad completa ni una compra.</p></div>`;
 document.querySelectorAll('.supply input').forEach(input=>input.addEventListener('change',()=>{input.checked?planSelection.add(input.value):planSelection.delete(input.value);updateBudget();document.querySelector('#challenge').hidden=true;document.querySelector('#plan-reflection').hidden=true;feedback('');}));
 on('check-plan','click',()=>{const r=evaluatePlan([...planSelection],budget);let messages=[];if(r.missing.length)messages.push(`Falta resolver: ${r.missing.join(', ')}.`);if(r.overBudget)messages.push(`El plan supera el presupuesto por ${-r.remaining} fichas. ¿Qué podrías cambiar o dejar para otra ocasión?`);if(r.ready){messages.push(`Tu plan cubre lo necesario y deja ${r.remaining} fichas. No es la única solución: ¿por qué elegiste esta?`);document.querySelector('#challenge').hidden=challenge;document.querySelector('#plan-reflection').hidden=false;}feedback(messages.join(' '));});
 on('plan-hint','click',()=>feedback('Empieza por lo necesario. Agua y revisar la ruta no gastan fichas. Compara las dos meriendas antes de elegir los extras.'));
 on('challenge','click',()=>{budget=5;challenge=true;renderPlan();document.querySelector('.supply input').focus();feedback('Cambio de situación: ahora tienes 5 fichas. Conservamos tus elecciones para que puedas revisarlas.');});
 on('reset-plan','click',()=>{budget=8;challenge=false;planSelection.clear();renderPlan();document.querySelector('.supply input').focus();feedback('Plan reiniciado. Tienes 8 fichas.');});updateBudget();
}
function updateBudget(){const r=evaluatePlan([...planSelection],budget);document.querySelector('#budget-summary').textContent=`Presupuesto: ${budget} fichas · Elegido: ${r.total} · ${r.remaining>=0?'Disponibles: '+r.remaining:'Exceso: '+(-r.remaining)}`;}
function renderCaregiver(){const toddler=stage==='18m';document.querySelector('#activity').innerHTML=`<p class="eyebrow">FUERA DE PANTALLA · EL ADULTO ACOMPAÑA</p><h4>${toddler?'Mi turno, tu turno':'Dos pasos, muchas historias'}</h4><p>${toddler?'Prepara una pelota grande y blanda adecuada a la edad, en un espacio despejado.':'Prepara un muñeco y una tela grande adecuada al juego, bajo supervisión directa.'}</p><ol class="steps"><li>${toddler?'Siéntate cerca y haz rodar la pelota suavemente.':'Muestra una secuencia breve: saludar al muñeco y arroparlo.'}</li><li>${toddler?'Espera su respuesta. Puede mirar, tocar, empujar o proponerte otra cosa.':'Invita a imitar o cambiar la historia. Puedes mostrar un paso cada vez.'}</li><li>${toddler?'Nombra lo que ocurre y sigue su iniciativa, sin exigir devolver la pelota.':'Pregunta «¿y ahora qué?» y da tiempo para responder con gestos o palabras.'}</li></ol><p class="notice">Guarda la pantalla durante el juego. Usa materiales seguros, sin piezas pequeñas, y supervisión directa. Si aparece cansancio o frustración, simplifica o para.</p><div class="reflection"><h4>Para observar, sin examinar</h4><p>${toddler?'¿Qué captó su interés? ¿Cómo te invitó a continuar?':'¿Qué parte eligió repetir o cambiar? ¿Qué ayuda le resultó útil?'}</p><p>No hace falta registrar respuestas ni completar todos los pasos.</p></div>`;}
function renderRoadmap(){document.querySelector('#activity').innerHTML=`<p class="eyebrow">EN DISEÑO · TODAVÍA NO ES UNA ACTIVIDAD INTERACTIVA</p><h4>${stage==='5y'?'Una historia que puedes ordenar':'Un proyecto con decisiones reales'}</h4><p>${stage==='5y'?'Próximo módulo propuesto: ordenar pasos de una tarea cotidiana, detectar qué falta y explicar otra secuencia posible. Se prevén apoyos visuales y acompañamiento lector.':'Próximo módulo propuesto: definir una meta elegida, comparar fuentes y alternativas, presupuestar recursos y justificar decisiones. Se prevén retos de argumentación y revisión entre perspectivas.'}</p><p class="notice">Antes de ampliar: revisar el contenido con especialistas, probar accesibilidad y comprensión, y decidir cómo observar aprendizaje fuera del juego con consentimiento.</p>`;}
renderStages();renderPanel();
